<script lang="ts">
 import { onMount } from 'svelte';
 import LooseFiles from './LooseFiles.svelte';
  import CatalogTree from './CatalogTree.svelte';
 import Player from './Player.svelte';
 import { destinationAfterLogin, findLesson, href, locationFromHash, type Route } from './router';
 import { transport, type Catalog, type Lesson, type User } from './transport';
 import { initialView, resolveSession, type ConfigState } from './session';
 let route: Route = locationFromHash(location.hash).route;
 let lessonPath: string | null = locationFromHash(location.hash).lessonPath;
 let user: User | null = null; let catalog: Catalog | null = null; let lesson: Lesson | null = null; let config: ConfigState = 'unknown';
  let loading = true; let error = ''; let username = ''; let password = ''; let currentPassword = ''; let rescanning = false; let rescanMessage = ''; let mediaError = '';
 onMount(() => { const change = () => { const next = locationFromHash(location.hash); route = next.route; lessonPath = next.lessonPath; lesson = findLesson(catalog, lessonPath); mediaError = ''; }; window.addEventListener('hashchange', change); void initialize(); return () => window.removeEventListener('hashchange', change); });
  async function initialize() { try { const session = await resolveSession(() => transport.me(), () => transport.config()); user = session.user; config = session.config; error = session.error; if (user && !user.mustChangeCredentials) { catalog = await transport.catalog(); lesson = findLesson(catalog, lessonPath); if (route === 'login') route = 'home'; } } catch { error = 'Não foi possível conectar ao serviço.'; } finally { loading = false; } }
  async function login(event: SubmitEvent) { event.preventDefault(); error = ''; loading = true; const destination = location.hash; try { user = await transport.login(username, password); password = ''; if (!user.mustChangeCredentials) { catalog = await transport.catalog(); lesson = findLesson(catalog, lessonPath); location.hash = destinationAfterLogin(destination); } } catch (cause) { error = cause instanceof Error ? cause.message : 'Não foi possível entrar.'; } finally { loading = false; } }
  async function credentials(event: SubmitEvent) { event.preventDefault(); error = ''; loading = true; try { user = await transport.updateCredentials(username, password, currentPassword); username = ''; password = ''; currentPassword = ''; catalog = await transport.catalog(); lesson = findLesson(catalog, lessonPath); location.hash = destinationAfterLogin(location.hash); } catch (cause) { error = cause instanceof Error ? cause.message : 'Não foi possível atualizar as credenciais.'; } finally { loading = false; } }
 async function logout() { await transport.logout(); user = null; catalog = null; lesson = null; location.hash = href('login'); }
 function syncLesson(nextCatalog: Catalog) { catalog = nextCatalog; lesson = findLesson(nextCatalog, lessonPath); mediaError = ''; }
 async function rescan() { rescanning = true; rescanMessage = 'Lendo a biblioteca…'; try { await transport.rescan(); syncLesson(await transport.catalog()); rescanMessage = 'Catálogo atualizado.'; } catch (cause) { rescanMessage = cause instanceof Error ? cause.message : 'Falha ao indexar.'; } finally { rescanning = false; } }
 function mediaFailed() { mediaError = 'Não foi possível carregar esta mídia.'; }
</script>
<svelte:head><title>LearnVault — sua biblioteca de estudos</title><meta name="description" content="Sua biblioteca pessoal de cursos." /></svelte:head>
{#if loading}<div class="loading" aria-live="polite">Carregando sua biblioteca…</div>
{:else if initialView(user, config) === 'offline'}<main class="login-page"><div class="brand"><span class="mark">LV</span> LEARNVAULT</div><section><p class="eyebrow">MODO OFFLINE</p><h1>Biblioteca não configurada</h1><p class="intro">Este aplicativo ainda não tem uma biblioteca configurada. A escolha da pasta da biblioteca chega em uma próxima atualização.</p></section></main>
{:else if !user}<main class="login-page"><div class="brand"><span class="mark">LV</span> LEARNVAULT</div><section><p class="eyebrow">SEU ESPAÇO DE APRENDIZAGEM</p><h1>Conhecimento,<br /><em>no seu ritmo.</em></h1><p class="intro">Uma casa tranquila para seus cursos, ideias e próximos passos.</p><form onsubmit={login}><label>Usuário<input autocomplete="username" bind:value={username} required /></label><label>Senha<input type="password" autocomplete="current-password" bind:value={password} required /></label>{#if error}<p class="error" role="alert">{error}</p>{/if}<button disabled={loading}>Entrar</button></form></section></main>
{:else if user.mustChangeCredentials}<main class="login-page"><section><h1>Configure sua conta</h1><p>Defina seu usuário e sua senha para continuar.</p><form onsubmit={credentials}><label>Senha atual<input type="password" autocomplete="current-password" bind:value={currentPassword} required /></label><label>Novo usuário<input autocomplete="username" bind:value={username} required /></label><label>Nova senha<input type="password" autocomplete="new-password" bind:value={password} required /></label>{#if error}<p class="error" role="alert">{error}</p>{/if}<button disabled={loading}>Continuar</button></form></section></main>
{:else}<div class="shell"><header><div class="brand"><span class="mark">LV</span> LEARNVAULT</div><button class="text-button" onclick={logout}>Sair</button></header><div class="layout"><aside aria-label="Navegação principal"><a class:active={route === 'home'} href={href('home')}>Início</a><a class:active={route === 'catalog'} href={href('catalog')}>Catálogo</a></aside><main><p class="eyebrow">BIBLIOTECA PESSOAL</p>{#if error}<p class="error" role="alert">{error}</p>{/if}{#if route === 'home'}<h1>Olá, {user.username}.</h1><p class="intro">Sua biblioteca está protegida e pronta para estudar.</p><a class="primary" href={href('catalog')}>Abrir catálogo</a>{:else if route === 'catalog'}<h1>Seus cursos</h1>{#if user.role === 'admin'}<button class="primary" onclick={rescan} disabled={rescanning}>{rescanning ? 'Indexando…' : 'Indexar biblioteca'}</button><p class="catalog-message" aria-live="polite">{rescanMessage}</p>{/if}{#if catalog && catalog.looseFiles.length}<LooseFiles files={catalog.looseFiles} heading="Arquivos soltos" />{/if}{#if catalog && catalog.nodes.length}<CatalogTree nodes={catalog.nodes} openLesson={(item) => { lesson = item; lessonPath = item.path; location.hash = href('player', item.path); }} />{:else if !catalog || !catalog.looseFiles.length}<p class="empty">O catálogo ainda está vazio.</p>{/if}{:else}<h1>{lesson?.title ?? 'Aula não encontrada'}</h1>{#if !lesson}<p class="empty" role="status">Não foi possível encontrar esta aula no catálogo atual.</p>{:else}<Player lesson={lesson} mediaError={mediaError} onMediaError={mediaFailed} />{/if}<a class="back" href={href('catalog')}>Voltar ao catálogo</a>{/if}</main></div></div>{/if}
